#include <stdint.h>
static uint64_t hash=UINT64_C(14695981039346656037);
static void byte(unsigned b){hash^=b;hash*=UINT64_C(1099511628211);}
static DdNode *truth(DdManager *dd,unsigned table,int level){DdNode *t,*e,*r;unsigned width,mask;if(level==3)return(table&1)?dd->one:Cudd_Not(dd->one);width=1u<<(2-level);mask=(1u<<width)-1;t=truth(dd,table>>width,level+1);Cudd_Ref(t);e=truth(dd,table&mask,level+1);Cudd_Ref(e);r=Cudd_bddIte(dd,dd->vars[level],t,e);Cudd_Ref(r);Cudd_RecursiveDeref(dd,t);Cudd_RecursiveDeref(dd,e);Cudd_Deref(r);return r;}
static unsigned bits(DdManager *dd,DdNode *f){unsigned result=0;int a,v,input[6];for(a=0;a<8;a++){for(v=0;v<6;v++)input[v]=v<3?((a>>(2-v))&1):0;if(Cudd_Eval(dd,f,input)==dd->one)result|=1u<<a;}return result;}
static unsigned equations(DdManager *dd,DdNode *f,unsigned mask){if(f==dd->zero)return 0;if(f==dd->one)return 1u<<mask;return equations(dd,cuddE(f),mask)|equations(dd,cuddT(f),mask|(1u<<(f->index/2)));}
static void bcollect(DdManager *dd,DdNode *f){Cudd_Ref(f);byte(bits(dd,f));Cudd_RecursiveDeref(dd,f);}
static void zcollect(DdManager *dd,DdNode *f){Cudd_Ref(f);byte(equations(dd,f,0));Cudd_RecursiveDerefZdd(dd,f);}
static DdNode *matrix(DdManager *dd,unsigned family){DdNode *result=dd->zero,*cube,*temp;int member,v;Cudd_Ref(result);for(member=0;member<8;member++){if(!(family&(1u<<member)))continue;cube=dd->one;Cudd_Ref(cube);for(v=0;v<3;v++)if(member&(1<<v)){temp=Cudd_zddChange(dd,cube,2*v);Cudd_Ref(temp);Cudd_RecursiveDerefZdd(dd,cube);cube=temp;}temp=Cudd_zddUnion(dd,result,cube);Cudd_Ref(temp);Cudd_RecursiveDerefZdd(dd,result);Cudd_RecursiveDerefZdd(dd,cube);result=temp;}Cudd_Deref(result);return result;}
int main(void){DdManager *dd=Cudd_Init(6,12,CUDD_UNIQUE_SLOTS,CUDD_CACHE_SLOTS,0);DdNode *functions[256],*p,*n,*m;int a,b;Cudd_zddVarsFromBddVars(dd,2);for(a=0;a<256;a++){functions[a]=truth(dd,a,0);Cudd_Ref(functions[a]);}for(a=0;a<256;a++){DdNode *f=functions[a];bcollect(dd,Extra_bddSpaceFromFunctionPos(dd,f));bcollect(dd,Extra_bddSpaceFromFunctionNeg(dd,f));bcollect(dd,Extra_bddSpaceCanonVars(dd,f));bcollect(dd,Extra_bddSpaceFromFunction(dd,f,f));bcollect(dd,Extra_bddSpaceFromFunctionFast(dd,f));p=Extra_bddSpaceEquationsPos(dd,f);Cudd_Ref(p);n=Extra_bddSpaceEquationsNeg(dd,f);Cudd_Ref(n);zcollect(dd,p);zcollect(dd,n);zcollect(dd,Extra_bddSpaceEquations(dd,f));bcollect(dd,Extra_bddSpaceFromMatrixPos(dd,n));bcollect(dd,Extra_bddSpaceFromMatrixNeg(dd,p));for(b=0;b<256;b++)bcollect(dd,Extra_bddSpaceFromFunction(dd,f,functions[b]));Cudd_RecursiveDerefZdd(dd,p);Cudd_RecursiveDerefZdd(dd,n);}for(a=0;a<256;a++){m=matrix(dd,a);Cudd_Ref(m);bcollect(dd,Extra_bddSpaceFromMatrixPos(dd,m));bcollect(dd,Extra_bddSpaceFromMatrixNeg(dd,m));Cudd_RecursiveDerefZdd(dd,m);}printf("%016llx\n",(unsigned long long)hash);Cudd_Quit(dd);return 0;}
